import{_ as s,l as i,o as e,c as o,v as t,p as l,x as r,d as n,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const R=JSON.parse('{"title":"QUIC 流与 0-RTT","description":"","frontmatter":{"title":"QUIC 流与 0-RTT","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/quic-streams-0rtt.md","filePath":"cs/quic-streams-0rtt.md","lastUpdated":1789023840000}'),d={name:"cs/quic-streams-0rtt.md"};function C(h,a,u,P,_,m){const T=i("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="quic-流与-0-rtt" tabindex="-1">QUIC 流与 0-RTT <a class="header-anchor" href="#quic-流与-0-rtt" aria-label="Permalink to &quot;QUIC 流与 0-RTT&quot;">​</a></h1><div class="epigraph"><p>QUIC 在 UDP 上做加密运输：多流免 TCP 队头阻塞，TLS 1.3 进握手；0-RTT 用上次票再发数据，有重放代价。</p><footer>—— 据 RFC 9000 QUIC；RFC 9001 使用 TLS；RFC 8446 TLS 1.3 整理</footer></div><p>主干<a href="/cs/quic-contrast">QUIC 对照</a> 已给动机。<a href="/cs/http2">HTTP/2</a> 多流仍落在一条 TCP 上。<a href="/cs/sctp">上一课</a> 对照多流。缺口是 <strong>QUIC 流与 0-RTT</strong>：stream ID、加密、早数据。本课不把连接迁移写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>TCP+TLS：两次握手 RTT，且 TCP 丢包挡住所有 HTTP/2 流。QUIC：运输与加密一体，握手 1-RTT，会话票可 0-RTT 发请求。流独立丢失恢复（包号与流偏移分离）。0-RTT 数据可被重放，只适合幂等——后课重试会收回。UDP 被中间限速是部署税。</p><p>不要把 0-RTT 写成「无密钥」。</p><p><span class="marginnote">RFC 9000。拥塞仍在连接级，避免每流 AIMD 加倍。本课不把帧类型列完。</span></p><h3 id="运输与-tls-一体" tabindex="-1">运输与 TLS 一体 <a class="header-anchor" href="#运输与-tls-一体" aria-label="Permalink to &quot;运输与 TLS 一体&quot;">​</a></h3><p>多流免 TCP HOL。0-RTT 有重放，只适合幂等。拥塞在连接级。UDP 被限则回退。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：TCP HOL vs QUIC 流。画：TLS 密钥 → 包保护 → 多 STREAM 帧。与 SYN cookies：QUIC Retry 抗泛洪。</p>',11)),(e(),l(p,null,{default:r(()=>[c(T,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20TLS%5B%22TLS%201.3%20%E8%BF%9B%20QUIC%22%5D%20--%3E%20KEY%5B%22%E5%8C%85%E4%BF%9D%E6%8A%A4%22%5D%0A%20%20KEY%20--%3E%20ST%5B%22%E5%A4%9A%E6%B5%81%22%5D%0A%20%20TKT%5B%22%E4%BC%9A%E8%AF%9D%E7%A5%A8%22%5D%20--%3E%20Z%5B%220-RTT%20%E6%97%A9%E6%95%B0%E6%8D%AE%22%5D%0A%20%20Z%20--%3E%20REP%5B%22%E9%87%8D%E6%94%BE%E9%A3%8E%E9%99%A9%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>TSO 变成 UDP GSO。ECN 计数在 QUIC 里。PMTUD 在用户态。BBR 常与 QUIC 同部署。SCTP 多流无 Web 加密集成。窗口是流控窗口+拥塞窗口两层，类似 HTTP/2 但加密。</p><p>握手失败回退 TCP 是浏览器政策，不是协议强制。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 DATAGRAM 扩展全文。QUIC 连接迁移是下一课。后课默认：QUIC 多流+集成 TLS；0-RTT 仅幂等。</p><p>公司防火墙「UDP 危险」会把用户打回 TCP HOL。</p><p>上一课留下的缺口在本课收口；「QUIC 流与 0-RTT」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/quic-migration">QUIC 连接迁移</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>多流消除运输队头阻塞。</li><li>1-RTT 握手，0-RTT 有重放。</li><li>拥塞在连接级，流控在流级。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 9000；RFC 9001；RFC 8446。</li></ul>',10))])}const A=s(d,[["render",C]]);export{R as __pageData,A as default};
